    url: "https://github.com/advisories/GHSA-2p57-rm9w-gvfp"
  },
  {
    package: "tar-fs",
    version: "2.1.1",
    cve: "CVE-2024-44082",
    severity: "HIGH",
    cvss: 7.5,
    fixedVersion: "2.1.4",
    title: "tar-fs has a symlink validation bypass if destination directory is predictable with a specific tarball",
    url: "https://github.com/advisories/GHSA-vj76-c3g6-qr5v"
  },
  {
    package: "ws",
    version: "7.5.7",
    cve: "CVE-2024-37890",
    severity: "HIGH",
    cvss: 7.5,
    fixedVersion: "7.5.10",
    title: "ws affected by a DoS when handling a request with many HTTP headers",
    url: "https://github.com/advisories/GHSA-3h5v-q93c-6h6q"
  },
  {
    package: "yaml",
    version: "2.1.1",
    cve: "CVE-2023-2251",
    severity: "HIGH",
    cvss: 7.5,
    fixedVersion: "2.2.2",
    title: "Uncaught Exception in yaml",
    url: "https://github.com/advisories/GHSA-f9xv-q969-pqx4"
  }
];

// Combine and deduplicate (prefer trivy for same package/CVE as it has verified CVE)
const allVulns = [...trivyVulns];
const seenKeys = new Set(trivyVulns.map(v => `${v.package}:${v.cve}`));

for (const vuln of npmAuditVulns) {
  const key = `${vuln.package}:${vuln.cve}`;
  if (!seenKeys.has(key)) {
    allVulns.push(vuln);
    seenKeys.add(key);
  }
}

// Sort by severity (CRITICAL first, then HIGH) and then by package name
allVulns.sort((a, b) => {
  if (a.severity === 'CRITICAL' && b.severity !== 'CRITICAL') return -1;
  if (a.severity !== 'CRITICAL' && b.severity === 'CRITICAL') return 1;
  return a.package.localeCompare(b.package);
});

// Generate CSV
const header = "Package,Version,CVE_ID,Severity,CVSS_Score,Fixed_Version,Title,Url";
const rows = allVulns.map(v => {
  // Escape quotes in title
  const escapedTitle = v.title.replace(/"/g, '""');
  return `${v.package},${v.version},${v.cve},${v.severity},${v.cvss},${v.fixedVersion},"${escapedTitle}",${v.url}`;
});

const csv = [header, ...rows].join('\n');
fs.writeFileSync('/root/security_audit.csv', csv);
console.log('CSV generated successfully!');
console.log(`Total vulnerabilities: ${allVulns.length}`);
console.log(`Critical: ${allVulns.filter(v => v.severity === 'CRITICAL').length}`);
console.log(`High: ${allVulns.filter(v => v.severity === 'HIGH').length}`);

